//! The enemy distances the Quick Mission Creator offers, fixed per theater
//! and ground target (John, 2026-10-28): a checked-in table measured once
//! offline with the launch solver, so neither the creator nor a server loads
//! terrain to decide. The table is generated by `tore-app
//! --qmc-distance-table` (docs/DEVELOPMENT.md, "Quick Mission distance
//! table"); the measurements are in
//! docs/baselines/qmc-distance-table.md. Launch still refuses a distance
//! that does not fit ([`super::availability::distance_problem`]).
//!
//! Each mask holds one bit per [`SEPARATION_NM`] choice, bit 0 for 1 nm.

use super::SEPARATION_NM;
use crate::mission::MissionSpec;

/// Every distance.
pub const ALL: u16 = (1 << SEPARATION_NM.len()) - 1;

/// One theater's distances with no ground target (or with area defenses,
/// which place no start): `airborne` for an airborne start, in every
/// situation and enemy formation; `ground` for a ground start at any of the
/// player's offered airfields, with any wing size.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Theater {
    pub code: &'static str,
    pub airborne: u16,
    pub ground: u16,
}

/// A ground target's airborne distances, listed only where they differ from
/// its theater's `airborne` row. A ground start with a ground target offers
/// every distance: the target's template places the enemy.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Target {
    pub theater: &'static str,
    pub stem: &'static str,
    pub airborne: u16,
}

/// What a ground target's layout leaves out in every measured layout (a
/// carrier's deck aircraft no supported deck holds), which the creator
/// shows while the target is chosen. Layout limitations that depend on the
/// seed are not listed: launch refuses or reports those.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Note {
    pub theater: &'static str,
    pub stem: &'static str,
    pub text: &'static str,
}

include!("distance_table_data.rs");

/// The note for ground target `stem` of `theater`, if it has one.
pub fn note(theater: &str, stem: &str) -> Option<&'static str> {
    NOTES
        .iter()
        .find(|note| note.theater == theater && note.stem == stem)
        .map(|note| note.text)
}

/// The distances offered for `theater`, ground target `target` (its
/// template stem) and a ground (`true`) or airborne start. A theater the
/// table does not hold (a developer `~` layout) offers every distance and
/// relies on the launch check.
pub fn allowed(theater: &str, target: Option<&str>, ground: bool) -> u16 {
    if let Some(stem) = target {
        if ground {
            return ALL;
        }
        if let Some(row) = TARGETS
            .iter()
            .find(|row| row.theater == theater && row.stem == stem)
        {
            return row.airborne;
        }
    }
    THEATERS
        .iter()
        .find(|row| row.code == theater)
        .map_or(ALL, |row| {
            if ground && target.is_none() {
                row.ground
            } else {
                row.airborne
            }
        })
}

/// The distances offered for `spec`.
pub fn allowed_for(spec: &MissionSpec) -> u16 {
    allowed(
        &spec.theater,
        spec.ground_target.as_deref(),
        spec.start.on_ground(),
    )
}

/// The choice (an index into [`SEPARATION_NM`]) that `index` becomes under
/// `mask`: itself when offered, else the largest offered one below it, else
/// the smallest offered one above it. An empty mask leaves it as it is.
pub fn clamp_index(mask: u16, index: usize) -> usize {
    let offered = |i: &usize| mask & (1 << i) != 0;
    let last = SEPARATION_NM.len() - 1;
    (0..=index.min(last))
        .rev()
        .find(offered)
        .or_else(|| (index.min(last)..=last).find(offered))
        .unwrap_or(index)
}

/// Moves `spec`'s distance to an offered one, as the creator does. Returns
/// the old and new distance in nautical miles when it moved, for a server's
/// log; `None` when the distance was already offered.
pub fn adjust(spec: &mut MissionSpec) -> Option<(u32, u32)> {
    let old = spec.separation_nm;
    let index = SEPARATION_NM.iter().position(|nm| *nm == f64::from(old))?;
    let new = SEPARATION_NM[clamp_index(allowed_for(spec), index)] as u32;
    (new != old).then(|| {
        spec.separation_nm = new;
        (old, new)
    })
}

/// The server log's line for a distance [`adjust`] moved.
pub fn adjust_notice(spec: &MissionSpec, (old, new): (u32, u32)) -> String {
    let target = spec
        .ground_target
        .as_deref()
        .map_or("no ground target".to_owned(), |stem| {
            format!("ground target {stem}")
        });
    let start = if spec.start.on_ground() {
        "a ground start"
    } else {
        "an airborne start"
    };
    format!(
        "separation-nm {old} is not offered for {} with {target} and {start}; using {new} nm, the creator's choice there.",
        spec.theater
    )
}

/// The offered distances in nautical miles, ascending.
pub fn miles(mask: u16) -> Vec<u32> {
    SEPARATION_NM
        .iter()
        .enumerate()
        .filter(|(i, _)| mask & (1 << i) != 0)
        .map(|(_, nm)| *nm as u32)
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::mission::Start;
    use tore_formats::{aircraft::AircraftId, quick_template::tables};

    #[test]
    fn every_creator_theater_and_target_has_a_row() {
        for code in tables::THEATERS {
            let row = THEATERS.iter().find(|row| row.code == code);
            let row = row.unwrap_or_else(|| panic!("{code} has no row"));
            assert_ne!(row.airborne, 0, "{code} offers no airborne distance");
            assert_ne!(row.ground, 0, "{code} offers no ground distance");
            assert_eq!(row.airborne & !ALL, 0);
            assert_eq!(row.ground & !ALL, 0);
        }
        assert_eq!(THEATERS.len(), tables::THEATERS.len());
        for row in TARGETS {
            assert!(
                crate::mission::ground_targets(row.theater).contains(&row.stem),
                "{} is not a target of {}",
                row.stem,
                row.theater
            );
            let theater = THEATERS.iter().find(|t| t.code == row.theater).unwrap();
            assert_ne!(row.airborne, theater.airborne, "{} repeats", row.stem);
            assert_ne!(row.airborne, 0);
        }
    }

    #[test]
    fn a_ground_start_with_a_target_offers_everything() {
        for code in tables::THEATERS {
            for stem in crate::mission::ground_targets(code) {
                assert_eq!(allowed(code, Some(stem), true), ALL);
            }
        }
        assert_eq!(allowed("~UKR1", None, false), ALL);
    }

    #[test]
    fn clamping_takes_the_largest_offered_at_or_below_else_the_nearest_above() {
        let mask = 0b000_0011_1100; // 5, 10, 20 and 50 nm
        assert_eq!(clamp_index(mask, 3), 3);
        assert_eq!(clamp_index(mask, 10), 5);
        assert_eq!(clamp_index(mask, 7), 5);
        assert_eq!(clamp_index(mask, 0), 2);
        assert_eq!(clamp_index(mask, 1), 2);
        assert_eq!(clamp_index(0, 4), 4);
        assert_eq!(clamp_index(ALL, 10), 10);
    }

    #[test]
    fn adjust_moves_only_a_distance_the_table_leaves_out() {
        let row = THEATERS
            .iter()
            .find(|row| row.airborne != ALL)
            .expect("some theater leaves a distance out");
        let mut spec = MissionSpec::new(row.code, AircraftId::F18);
        spec.separation_nm = 300;
        let top = *miles(row.airborne).last().unwrap();
        assert_eq!(adjust(&mut spec), Some((300, top)));
        assert_eq!(spec.separation_nm, top);
        assert_eq!(adjust(&mut spec), None);
        spec.separation_nm = 1;
        assert_eq!(adjust(&mut spec), None);
        // A ground target's ground start keeps any distance.
        if let Some(stem) = crate::mission::ground_targets(row.code).first() {
            spec.ground_target = Some((*stem).into());
            spec.start = Start::GroundAuto { altitude_ft: 5000 };
            spec.separation_nm = 300;
            assert_eq!(adjust(&mut spec), None);
        }
        let kurile = MissionSpec::new("KURILE", AircraftId::F18);
        assert_eq!(
            adjust_notice(&kurile, (300, 200)),
            "separation-nm 300 is not offered for KURILE with no ground target and an airborne start; using 200 nm, the creator's choice there."
        );
    }
}
